/* Offline Mermaid 11.4.1 renderer, gzip-packed to fit the repository file limit.
 * MIT license: see MERMAID-LICENSE. Dependency notices remain in the decoded bundle.
 * Uses the browser DecompressionStream API before initializing the guide.
 */
window.mermaidReady = (async () => {
  const bytes = Uint8Array.from(atob(""), c => c.charCodeAt(0));
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
  const script = document.createElement("script");
  script.textContent = await new Response(stream).text();
  document.head.appendChild(script);
})();
